import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

const App = () => {
    // State variables for the application
    const [categories, setCategories] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [isTreeVisible, setIsTreeVisible] = useState(false);
    const [selectedCategory, setSelectedCategory] = useState(null);
    const [currentPage, setCurrentPage] = useState('home'); // 'home' or 'products'
    const [products, setProducts] = useState([]);
    const [productsLoading, setProductsLoading] = useState(false);

    const timerRef = useRef(null);
    const buttonRef = useRef(null);

    // Fetch categories on component mount
    useEffect(() => {
        const fetchCategories = async () => {
            try {
                // Now fetching data from the backend API
                const response = await axios.get('http://localhost:8080/category');
                setCategories(response.data);
            } catch (err) {
                setError(err);
            } finally {
                setLoading(false);
            }
        };
        fetchCategories();
    }, []);

    // Effect to fetch products when currentPage and selectedCategory change
    useEffect(() => {
        if (currentPage === 'products' && selectedCategory) {
            setProductsLoading(true);
            const fetchProducts = async () => {
                try {
                    // Mock API call to simulate fetching products for the selected category
                    const response = await new Promise(resolve => setTimeout(() => {
                        const mockData = Array.from({ length: 5 }, (_, i) => ({
                            id: i + 1,
                            name: `${selectedCategory.name} Produktas ${i + 1}`,
                            price: `€${(10 + i * 5).toFixed(2)}`,
                        }));
                        resolve({ data: mockData });
                    }, 500));
                    setProducts(response.data);
                } catch (err) {
                    console.error("Failed to fetch products:", err);
                } finally {
                    setProductsLoading(false);
                }
            };
            fetchProducts();
        }
    }, [currentPage, selectedCategory]);

    // Handle mouse enter for delayed tree visibility
    const showTreeWithDelay = () => {
        if (timerRef.current) clearTimeout(timerRef.current);
        timerRef.current = setTimeout(() => {
            setIsTreeVisible(true);
        }, 300);
    };

    // Handle mouse leave for delayed tree hiding
    const hideTreeWithDelay = () => {
        if (timerRef.current) clearTimeout(timerRef.current);
        timerRef.current = setTimeout(() => {
            setIsTreeVisible(false);
            setSelectedCategory(null);
        }, 100);
    };

    // Handle a category click, which changes the page
    const handleCategoryClick = (category) => {
        setSelectedCategory(category);
        setCurrentPage('products');
        hideTreeWithDelay();
    };

    // Render the main application header with the category dropdown
    const renderHeader = () => (
        <div className="flex justify-between items-center py-4 px-6 bg-white shadow-lg rounded-lg mb-6">
            <h1
                className="text-2xl font-bold text-blue-600 cursor-pointer transition-colors duration-200 hover:text-blue-800"
                onClick={() => setCurrentPage('home')}
            >
                E-Shop
            </h1>
            <div className="relative inline-block">
                <button
                    ref={buttonRef}
                    onMouseEnter={showTreeWithDelay}
                    onMouseLeave={hideTreeWithDelay}
                    className="px-6 py-3 text-lg font-semibold text-white bg-blue-600 rounded-lg shadow-md hover:bg-blue-700 transition duration-300 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
                >
                    {isTreeVisible ? '▼ ' : '▶ '}
                    Kategorijos
                </button>
                {isTreeVisible && (
                    <div
                        onMouseEnter={showTreeWithDelay}
                        onMouseLeave={hideTreeWithDelay}
                        className="absolute top-full left-0 mt-2 flex flex-row rounded-lg bg-white border border-gray-200 shadow-xl z-10 transition-all duration-300 ease-in-out"
                        style={{ width: selectedCategory ? '800px' : '250px' }}
                    >
                        {/* Left Sidebar for categories */}
                        <div className="w-64 p-3 border-r border-gray-200">
                            {categories.map(category => (
                                <div
                                    key={category.id}
                                    onMouseEnter={() => setSelectedCategory(category)}
                                    onClick={() => handleCategoryClick(category)} // The core routing action
                                    className={`p-2 rounded-md cursor-pointer transition-colors duration-200 ${selectedCategory && selectedCategory.id === category.id ? 'bg-gray-100' : 'hover:bg-gray-50'}`}
                                >
                                    <span className="truncate">{category.name}</span>
                                </div>
                            ))}
                        </div>
                        {/* Right Content Area for subcategories */}
                        {selectedCategory && (
                            <div className="flex-1 p-4">
                                <h3 className="font-semibold text-lg text-gray-700 mb-4">{selectedCategory.name}</h3>
                                {selectedCategory.children && selectedCategory.children.length > 0 ? (
                                    <div className="space-y-4">
                                        {selectedCategory.children.map(child => (
                                            <div key={child.id}>
                                                <h4 className="font-medium text-md text-gray-600">{child.name}</h4>
                                                {child.children && child.children.length > 0 && (
                                                    <div className="flex flex-wrap gap-x-4">
                                                        {child.children.map(subChild => (
                                                            <span key={subChild.id} className="text-sm text-gray-500">
                                                                {subChild.name}
                                                            </span>
                                                        ))}
                                                    </div>
                                                )}
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <div className="text-gray-500 italic">No subcategories available.</div>
                                )}
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
    );

    // Renders the Home Page content
    const renderHomePage = () => {
        if (loading) {
            return <div className="text-center text-gray-500 mt-10">Loading categories...</div>;
        }
        if (error) {
            return <div className="text-center text-red-500 mt-10">Error: {error.message}</div>;
        }
        return (
            <div className="container mx-auto p-4 flex flex-col items-center">
                {renderHeader()}
                <div className="text-center mt-10 p-6 bg-gray-100 rounded-xl shadow-inner max-w-lg">
                    <h2 className="text-2xl font-semibold text-gray-700 mb-2">Sveiki atvykę į E-parduotuvę!</h2>
                    <p className="text-gray-600">
                        Pasirinkite kategoriją iš meniu, kad galėtumėte naršyti produktus.
                    </p>
                </div>
            </div>
        );
    };

    // Renders the Products Page content
    const renderProductsPage = () => {
        if (!selectedCategory) {
            return <div className="container mx-auto p-4 text-center">No category selected.</div>;
        }
        return (
            <div className="container mx-auto p-4">
                {renderHeader()}
                <button
                    onClick={() => setCurrentPage('home')}
                    className="mb-6 px-4 py-2 bg-gray-200 text-gray-800 rounded-lg hover:bg-gray-300 transition duration-300 shadow-sm"
                >
                    &larr; Grįžti į kategorijas
                </button>
                <h2 className="text-3xl font-bold text-gray-800 mb-6">{selectedCategory.name}</h2>
                {productsLoading ? (
                    <div className="text-center text-gray-500">Produktai kraunami...</div>
                ) : (
                    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
                        {products.map(product => (
                            <div key={product.id} className="bg-white rounded-lg shadow-md p-4">
                                <h3 className="text-lg font-semibold text-gray-700">{product.name}</h3>
                                <p className="text-gray-500 mt-1">{product.price}</p>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        );
    };

    // The main routing logic to decide which page to render
    let content;
    switch (currentPage) {
        case 'home':
            content = renderHomePage();
            break;
        case 'products':
            content = renderProductsPage();
            break;
        default:
            content = renderHomePage();
    }

    return (
        <div className="min-h-screen bg-gray-50 font-sans">
            <script src="https://cdn.tailwindcss.com"></script>
            {content}
        </div>
    );
};

export default App;
